import sys

def main():
    data = sys.stdin.read().split()
    a, b = data[2], data[3]
    if len(b) > len(a):
        a, b = b, a
    w = len(b)
    prev = [0] * (w + 1)
    for ch in a:
        cur = [0] * (w + 1)
        for j in range(1, w + 1):
            if b[j - 1] == ch:
                cur[j] = prev[j - 1] + 1
            else:
                x = prev[j]
                y = cur[j - 1]
                cur[j] = x if x > y else y
        prev = cur
    print(prev[w])

